+    }
+
+    form {
+      display: grid;
+      gap: 18px;
+    }
+
+    .form-field {
+      display: grid;
+      gap: 8px;
+    }
+
+    label {
+      font-weight: 600;
+      color: #f8fafc;
+    }
+
+    .hint,
+    .error-message {
+      font-size: 0.92rem;
+      line-height: 1.4;
