<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: rgba(16, 23, 42, 0.88);
      --panel-border: rgba(148, 163, 184, 0.18);
      --text: #e2e8f0;
      --muted: #94a3b8;
      --accent: #7c3aed;
      --accent-2: #22c55e;
      --error: #fb7185;
      --field-bg: #0f172a;
      --field-border: #334155;
      --shadow: 0 24px 80px rgba(2, 6, 23, 0.55);
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(124, 58, 237, 0.24), transparent 34%),
        radial-gradient(circle at bottom right, rgba(34, 197, 94, 0.14), transparent 26%),
        var(--bg);
      color: var(--text);
      display: grid;
      place-items: center;
      padding: 32px 16px;
    }

    .support-card {
      width: min(100%, 720px);
      background: var(--panel);
      border: 1px solid var(--panel-border);
      border-radius: 24px;
      box-shadow: var(--shadow);
      padding: 32px;
      backdrop-filter: blur(14px);
    }

    .eyebrow {
      margin: 0 0 8px;
      color: #c4b5fd;
      text-transform: uppercase;
      letter-spacing: 0.16em;
      font-size: 0.8rem;
      font-weight: 700;
    }

    h1 {
      margin: 0 0 12px;
      font-size: clamp(2rem, 3.5vw, 2.7rem);
      line-height: 1.1;
    }

    .subtitle {
      margin: 0 0 28px;
      color: var(--muted);
      line-height: 1.6;
      max-width: 60ch;
    }

    form {
      display: grid;
      gap: 18px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-weight: 600;
      color: #f8fafc;
    }

    .hint,
    .error-message {
      font-size: 0.92rem;
      line-height: 1.4;
    }

    .hint {
      color: var(--muted);
    }

    input {
      width: 100%;
      border: 1px solid var(--field-border);
      border-radius: 14px;
      background: var(--field-bg);
      color: var(--text);
      padding: 14px 16px;
      font-size: 1rem;
      outline: none;
      transition: border-color 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
    }

    input::placeholder {
      color: #64748b;
    }

    input:focus {
      border-color: rgba(124, 58, 237, 0.95);
      box-shadow: 0 0 0 4px rgba(124, 58, 237, 0.18);
    }

    .form-field.invalid input {
      border-color: var(--error);
      box-shadow: 0 0 0 4px rgba(251, 113, 133, 0.12);
    }

    .error-message {
      min-height: 1.25em;
      color: var(--error);
      margin: 0;
    }

    button {
      justify-self: start;
      border: 0;
      border-radius: 14px;
      padding: 14px 22px;
      font-size: 1rem;
      font-weight: 700;
      color: #fff;
      background: linear-gradient(135deg, #7c3aed, #22c55e);
      cursor: pointer;
      box-shadow: 0 16px 36px rgba(124, 58, 237, 0.28);
      transition: transform 0.18s ease, filter 0.18s ease;
    }

    button:hover {
      transform: translateY(-1px);
      filter: brightness(1.03);
    }

    button:active {
      transform: translateY(0);
    }

    .form-status {
      min-height: 1.25em;
      color: var(--accent-2);
      font-weight: 600;
      margin: 2px 0 0;
    }

    @media (max-width: 540px) {
      .support-card {
        padding: 24px;
        border-radius: 20px;
      }
    }
  </style>
</head>
<body>
  <main class="support-card">
    <p class="eyebrow">Support</p>
    <h1>Contact our team</h1>
    <p class="subtitle">Send us your details and we&apos;ll get back to you as soon as possible.</p>

    <form id="support-form" novalidate>
      <div class="form-field" data-field="fullName">
        <label for="fullName">Full name</label>
        <input id="fullName" name="fullName" type="text" autocomplete="name" placeholder="Jane Doe" required />
        <p class="error-message" id="fullName-error" aria-live="polite"></p>
      </div>

      <div class="form-field" data-field="email">
        <label for="email">Email address</label>
        <input id="email" name="email" type="email" autocomplete="email" placeholder="jane@example.com" required />
        <p class="error-message" id="email-error" aria-live="polite"></p>
      </div>

      <div class="form-field" data-field="phone">
        <label for="phone">Phone number</label>
        <input id="phone" name="phone" type="tel" autocomplete="tel" placeholder="(555) 123-4567" aria-describedby="phone-hint phone-error" />
        <p class="hint" id="phone-hint">Optional. Use (555) 123-4567 or 555-123-4567.</p>
        <p class="error-message" id="phone-error" aria-live="polite"></p>
      </div>

      <button type="submit">Send message</button>
      <p class="form-status" id="form-status" aria-live="polite"></p>
    </form>
  </main>

  <script>
    const form = document.getElementById('support-form');
    const fields = {
      fullName: document.getElementById('fullName'),
      email: document.getElementById('email'),
      phone: document.getElementById('phone'),
    };
    const status = document.getElementById('form-status');

    const validators = {
      fullName(value) {
        return value.trim() ? '' : 'Full name is required.';
      },
      email(value) {
        if (!value.trim()) return 'Email address is required.';
        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim()) ? '' : 'Enter a valid email address.';
      },
      phone(value) {
        if (!value.trim()) return '';
        return /^(\(\d{3}\)\s?\d{3}-\d{4}|\d{3}-\d{3}-\d{4})$/.test(value.trim())
          ? ''
          : 'Use a valid phone format such as (555) 123-4567.';
      },
    };

    function setFieldState(name, message) {
      const field = fields[name].closest('.form-field');
      const error = document.getElementById(`${name}-error`);
      const invalid = Boolean(message);

      field.classList.toggle('invalid', invalid);
      fields[name].setAttribute('aria-invalid', String(invalid));
      error.textContent = message;
    }

    function validateField(name) {
      const message = validators[name](fields[name].value);
      setFieldState(name, message);
      return !message;
    }

    Object.keys(fields).forEach((name) => {
      fields[name].addEventListener('blur', () => validateField(name));
      fields[name].addEventListener('input', () => {
        if (document.getElementById(`${name}-error`).textContent) {
          validateField(name);
        }
        status.textContent = '';
      });
    });

    form.addEventListener('submit', (event) => {
      event.preventDefault();

      const valid = Object.keys(fields).map(validateField).every(Boolean);
      if (!valid) {
        status.textContent = '';
        return;
      }

      status.textContent = 'Thanks — your message has been prepared for submission.';
      form.reset();
      Object.keys(fields).forEach((name) => setFieldState(name, ''));
    });
  </script>
</body>
</html>
