 <body>
   <main class="support-card">
     <p class="eyebrow">Support</p>
     <h1>Contact our team</h1>
     <p class="subtitle">Send us your details and we&apos;ll get back to you as soon as possible.</p>

     <form id="support-form" novalidate>
       <div class="form-field" data-field="fullName">
         <label for="fullName">Full name</label>
         <input id="fullName" name="fullName" type="text" autocomplete="name" placeholder="Jane Doe" required />
         <p class="error-message" id="fullName-error" aria-live="polite"></p>
       </div>

       <div class="form-field" data-field="email">
         <label for="email">Email address</label>
         <input id="email" name="email" type="email" autocomplete="email" placeholder="jane@example.com" required />
         <p class="error-message" id="email-error" aria-live="polite"></p>
       </div>

       <div class="form-field" data-field="phone">
         <label for="phone">Phone number</label>
         <input id="phone" name="phone" type="tel" autocomplete="tel" placeholder="(555) 123-4567" aria-describedby="phone-hint phone-error" />
         <p class="hint" id="phone-hint">Optional. Use (555) 123-4567 or 555-123-4567.</p>
         <p class="error-message" id="phone-error" aria-live="polite"></p>
       </div>

       <button type="submit">Send message</button>
       <p class="form-status" id="form-status" aria-live="polite"></p>
     </form>
   </main>

   <script>
     const form = document.getElementById('support-form');
     const fields = {
       fullName: document.getElementById('fullName'),
       email: document.getElementById('email'),
       phone: document.getElementById('phone'),
     };
     const status = document.getElementById('form-status');

     const validators = {
       fullName(value) {
         return value.trim() ? '' : 'Full name is required.';
       },
       email(value) {
         if (!value.trim()) return 'Email address is required.';
         return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim()) ? '' : 'Enter a valid email address.';
       },
       phone(value) {
         if (!value.trim()) return '';
         return /^(\(\d{3}\)\s?\d{3}-\d{4}|\d{3}-\d{3}-\d{4})$/.test(value.trim())
           ? ''
           : 'Use a valid phone format such as (555) 123-4567.';
       },
     };

     function setFieldState(name, message) {
       const field = fields[name].closest('.form-field');
       const error = document.getElementById(`${name}-error`);
       const invalid = Boolean(message);

       field.classList.toggle('invalid', invalid);
       fields[name].setAttribute('aria-invalid', String(invalid));
       error.textContent = message;
     }

     function validateField(name) {
       const message = validators[name](fields[name].value);
       setFieldState(name, message);
       return !message;
     }

     Object.keys(fields).forEach((name) => {
       fields[name].addEventListener('blur', () => validateField(name));
       fields[name].addEventListener('input', () => {
         if (document.getElementById(`${name}-error`).textContent) {
           validateField(name);
         }
         status.textContent = '';
       });
     });

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       const valid = Object.keys(fields).map(validateField).every(Boolean);
       if (!valid) {
         status.textContent = '';
         return;
       }

       status.textContent = 'Thanks — your message has been prepared for submission.';
       form.reset();
       Object.keys(fields).forEach((name) => setFieldState(name, ''));
     });
   </script>
